function make(): number {
  type Pair = { a: number; b: number };
  interface Named { label: string }
  const p: Pair = { a: 1, b: 2 };
  const n: Named = { label: "x" };
  return p.a + p.b + n.label.length;
}
function main(): void {
  type Local = { v: string };
  const l: Local = { v: "ok" };
  console.log(make(), l, l.v);
}
